def esc(s):return html.escape(str(s))
def count(s):return len(re.sub(r'\s','',s))
def tm(n):return f'{int(n)//60}:{int(n)%60:02d}'+('.5' if n%1 else '')
def table(head,rows):return '<div class="tablewrap"><table><thead><tr>'+''.join(f'<th>{x}</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def ul(xs):return '<ul>'+''.join('<li>'+x+'</li>' for x in xs)+'</ul>'
t=0
for c in cuts:c.update(at=t,vc=count(c['voice']),wc=sum(map(count,c['words'])));t+=c['sec']
vc=sum(c['vc'] for c in cuts);wc=sum(c['wc'] for c in cuts)
(P/'assets/planning/cuts.json').write_text(json.dumps(cuts,ensure_ascii=False,indent=2))
